"""Inspect actual Babylon assets, animation clocks, CCTV pixels and quality profiles.
The model lineup is an explicit render inspection fixture, not a gameplay screenshot.
"""
from playwright.sync_api import sync_playwright
import pathlib,json,os
ROOT=pathlib.Path(__file__).resolve().parent.parent;OUT=ROOT/'docs/screenshots';OUT.mkdir(parents=True,exist_ok=True)
url=os.environ.get('TURNO_URL','http://127.0.0.1:3000')
report={'platform':'Linux Chromium / SwiftShader; not Windows hardware','lineup':'Inspection fixture, rendered by the production Babylon scene'}
with sync_playwright() as pw:
 b=pw.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox','--use-angle=swiftshader','--enable-unsafe-swiftshader','--disable-background-timer-throttling','--disable-renderer-backgrounding']);p=b.new_page(viewport={'width':1440,'height':900});errors=[];external=[];p.on('request',lambda r:external.append(r.url) if not r.url.startswith((url,'data:','blob:')) else None);p.on('pageerror',lambda e:errors.append(str(e)));p.on('console',lambda m:errors.append(m.text[:1500]) if m.type=='error' else None)
 p.route('**/favicon.ico',lambda route:route.fulfill(status=204));p.goto(url+'/health');p.set_content('<style>body{margin:0;background:#000}#world{width:100vw;height:100vh}#feed{position:fixed;right:20px;bottom:20px;width:384px;height:216px}</style><canvas id="world"></canvas><canvas id="feed" hidden></canvas>');p.add_script_tag(url=url+'/vendor/babylon.js');p.add_script_tag(url=url+'/vendor/babylon-loaders.js')
 p.evaluate('''async()=>{const {Scene}=await import('/scene.js'),{newWorld,newPlayer}=await import('/shared/simulation.js');const scene=new Scene(document.querySelector('#world'),document.querySelector('#feed'));await scene.ready;scene.quality='normal';scene.resize();const world=newWorld();world.enemies.forEach((e,i)=>{e.x=(i-1.5)*1.4;e.z=0;});const me=newPlayer('inspection','Inspection');me.x=0;me.z=4.2;me.yaw=0;me.flashlight=false;const state={world,players:[me],started:true};window.probe={scene,state,me,look:{yaw:0,pitch:.07},last:performance.now()};function draw(t){const a=window.probe,dt=Math.min(.08,(t-a.last)/1000);a.last=t;a.scene.draw(a.state,a.me,a.look,dt,t/1000);requestAnimationFrame(draw);}requestAnimationFrame(draw);}''')
 p.wait_for_timeout(1800);p.screenshot(path=str(OUT/'v0.5-modelos.png'))
 report['assets']=p.evaluate('''()=>[...probe.scene.models].map(([id,m])=>({id,meshes:m.getChildMeshes().length,clips:m.metadata.groups.map(g=>g.name),frame:m.metadata.groups.find(g=>/Idle/.test(g.name)).animatables[0]?.masterFrame}))''')
 before=report['assets'][0]['frame'];p.wait_for_function('(frame)=>probe.scene.models.get("prisma").metadata.groups.find(g=>/Idle/.test(g.name)).animatables[0].masterFrame!==frame',arg=before);after=p.evaluate('()=>probe.scene.models.get("prisma").metadata.groups.find(g=>/Idle/.test(g.name)).animatables[0].masterFrame');assert after!=before;report['imported_idle_animation_advances']=True
 p.evaluate('''()=>{const e=probe.state.world.enemies[0];e.state='chase';e.x+=.7;}''');p.wait_for_function('()=>probe.scene.models.get("prisma").metadata.blend>0');assert p.evaluate('()=>probe.scene.models.get("prisma").metadata.blend')>0;report['walk_blends_with_motion']=True;p.evaluate('()=>{const e=probe.state.world.enemies[0];e.state="dormant";e.x=-2.1;}');p.wait_for_function('()=>Math.abs(probe.scene.models.get("prisma").rotation.y)<.02')
 def fps():return p.evaluate('''()=>new Promise(resolve=>{let start,count=0;function f(t){start??=t;count++;if(t-start<2200)requestAnimationFrame(f);else resolve(Math.round((count-1)*10000/(t-start))/10);}requestAnimationFrame(f);})''')
 report['normal_fps']=fps();p.evaluate('()=>{probe.scene.quality="low";probe.scene.resize();}');p.wait_for_timeout(500);report['low_fps']=fps();p.screenshot(path=str(OUT/'v0.5-modelos-ligero.png'));report['low_resolution']=p.evaluate('()=>[probe.scene.metrics.width,probe.scene.metrics.height]');report['metrics']=p.evaluate('()=>probe.scene.metrics');p.evaluate('()=>probe.scene.showScare("ember")');p.wait_for_function('()=>probe.scene.models.get("ember").metadata.attack.animatables[0]?.masterFrame>0');report['attack_clip_plays']=True
 # Main application: actual guard, controls, save and six different real feeds.
 p.goto(url,wait_until='networkidle');p.evaluate('()=>{const q=document.querySelector("#quality");q.value="low";q.dispatchEvent(new Event("change"));}');p.click('#solo');p.wait_for_selector('#ready',state='visible');p.click('#start');p.wait_for_selector('#ready',state='hidden');p.screenshot(path=str(OUT/'v0.5-seguridad.png'));report['single_guard_low_fps']=fps();p.keyboard.press('Tab');p.wait_for_selector('#phone',state='visible');hashes=[]
 for i in range(6):
  p.click(f'[data-camera="{i}"]');p.wait_for_function('(i)=>document.querySelector("#camera-feed").dataset.camera===String(i)',arg=i,timeout=30000)
  hashes.append(p.evaluate('''()=>{const c=document.querySelector('#camera-feed'),d=c.getContext('2d').getImageData(0,0,c.width,c.height).data;let h=0;for(let i=0;i<d.length;i+=101)h=(Math.imul(h,31)+d[i])|0;return h;}'''))
  if i==1:p.screenshot(path=str(OUT/'v0.5-camaras.png'))
 assert len(set(hashes))==6,hashes;report['six_live_camera_views']=True
 p.keyboard.press('Tab');p.wait_for_selector('#phone',state='hidden');p.keyboard.press('Escape');p.click('#save');p.wait_for_function('()=>document.querySelector("#save-status").textContent.includes("guardada")');report['manual_save']=True
 before=p.evaluate('()=>JSON.parse(localStorage.getItem("turno-cero.save")).players[0].x');p.click('#resume');p.keyboard.down('KeyW');p.wait_for_timeout(2400);p.keyboard.up('KeyW');p.keyboard.press('Escape');p.click('#save');p.wait_for_function('(x)=>JSON.parse(localStorage.getItem("turno-cero.save")).players[0].x>x+2',arg=before);report['movement_and_input_cadence']=True;p.click('#resume');p.evaluate('()=>{const q=document.querySelector("#quality");q.value="normal";q.dispatchEvent(new Event("change"));}');p.wait_for_timeout(1000);p.screenshot(path=str(OUT/'v0.5-restaurante.png'))
 print(json.dumps(report),flush=True);assert not errors,errors;assert not external,external;report['external_asset_requests']=external;report['errors']=errors;(OUT/'babylon-verification.json').write_text(json.dumps(report,indent=2));print(json.dumps(report));b.close()
